interface Logger {
  log(msg: string): void
}

class ConsoleLogger implements Logger {
  log(msg: string) { console.log(msg) }
}

class NoopLogger implements Logger {
  log(msg: string) { /* intentionally empty */ }
}

function createLogger(useConsole: boolean): Logger {
  return useConsole ? new ConsoleLogger() : new NoopLogger()
}

interface PaymentGateway {
  charge(amount: number): boolean
}

class RealGateway implements PaymentGateway {
  charge(amount: number) { /* network call */ return true }
}

class NoopGateway implements PaymentGateway {
  charge(amount: number) { return false }
}

class OrderService {
  constructor(private gateway: PaymentGateway = new NoopGateway()) {}
}

// Version A
class OrderProcessorA {
  constructor(private gateway?: PaymentGateway) {}

  process(amount: number) {
    if (this.gateway) {
      this.gateway.charge(amount)
    } else {
      // skip payment silently
    }
  }
}

// Version B
class NoopGateway implements PaymentGateway {
  charge(amount: number) { return false }
}

class OrderProcessorB {
  constructor(private gateway: PaymentGateway = new NoopGateway()) {}

  process(amount: number) {
    this.gateway.charge(amount)
  }
}
